package ml.inference

import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.{CountDownLatch, TimeUnit}
import scala.collection.concurrent.TrieMap
import scala.util.{Try, Success, Failure}

// Template engine for model response formatting
object TemplateEngine {
  private val templateCache = TrieMap.empty[String, CompiledTemplate]

  sealed trait TemplateNode
  case class LiteralNode(text: String) extends TemplateNode
  case class VariableNode(name: String) extends TemplateNode
  case class ExpressionNode(expr: String) extends TemplateNode

  case class CompiledTemplate(nodes: List[TemplateNode])

  def compile(template: String): CompiledTemplate = {
    templateCache.getOrElseUpdate(template, {
      val nodes = parseTemplate(template)
      CompiledTemplate(nodes)
    })
  }

  private def parseTemplate(template: String): List[TemplateNode] = {
    val pattern = """\$\{([^}]+)\}|\#\{([^}]+)\}""".r
    var lastEnd = 0
    val nodes = scala.collection.mutable.ListBuffer.empty[TemplateNode]

    pattern.findAllMatchIn(template).foreach { m =>
      if (m.start > lastEnd) {
        nodes += LiteralNode(template.substring(lastEnd, m.start))
      }
      if (m.group(1) != null) {
        nodes += VariableNode(m.group(1))
      } else if (m.group(2) != null) {
        nodes += ExpressionNode(m.group(2))
      }
      lastEnd = m.end
    }
    if (lastEnd < template.length) {
      nodes += LiteralNode(template.substring(lastEnd))
    }
    nodes.toList
  }

  def render(compiled: CompiledTemplate, context: Map[String, Any]): String = {
    compiled.nodes.map {
      case LiteralNode(text) => text
      case VariableNode(name) => context.getOrElse(name, "").toString
      case ExpressionNode(expr) => evaluateExpression(expr, context)
    }.mkString
  }

  private def evaluateExpression(expr: String, context: Map[String, Any]): String = {
    // Expression evaluation for template formatting
    val trimmed = expr.trim
    if (trimmed.startsWith("format:")) {
      val formatExpr = trimmed.stripPrefix("format:")
      applyFormat(formatExpr, context)
    } else {
      // Delegate to Scala runtime evaluation for complex expressions
      runtimeEval(trimmed, context)
    }
  }

  private def applyFormat(formatExpr: String, context: Map[String, Any]): String = {
    val parts = formatExpr.split("\\|")
    val varName = parts(0).trim
    val format = if (parts.length > 1) parts(1).trim else "default"
    val value = context.getOrElse(varName, "")
    format match {
      case "percent" => f"${value.toString.toDouble}%.2f%%"
      case "scientific" => f"${value.toString.toDouble}%.4e"
      case _ => value.toString
    }
  }

  private def runtimeEval(expr: String, context: Map[String, Any]): String = {
    import scala.tools.nsc.interpreter.IMain
    import scala.tools.nsc.Settings
    val settings = new Settings
    settings.usejavacp.value = true
    val imain = new IMain(settings)
    context.foreach { case (k, v) =>
      imain.bind(k, v.getClass.getName, v)
    }
    val result = imain.interpret(expr)
    imain.close()
    result.toString
  }
}

// Model inference result formatting
object ResponseFormatter {
  // Default template for inference results
  val DEFAULT_TEMPLATE = "Prediction: ${prediction}, Confidence: #{format:confidence|percent}"

  def formatResponse(modelOutput: Map[String, Any], templateOverride: Option[String] = None): String = {
    val template = templateOverride.getOrElse(DEFAULT_TEMPLATE)
    val compiled = TemplateEngine.compile(template)
    TemplateEngine.render(compiled, modelOutput)
  }
}

// ML Inference Server with graceful shutdown
class InferenceServer(port: Int) {
  private val isRunning = new AtomicBoolean(false)
  private val shutdownLatch = new CountDownLatch(1)
  private val activeRequests = new java.util.concurrent.atomic.AtomicInteger(0)

  def start(): Unit = {
    isRunning.set(true)
    Runtime.getRuntime.addShutdownHook(new Thread(() => gracefulShutdown()))
    println(s"Inference server started on port $port")
  }

  def handleInferenceRequest(modelId: String, input: Array[Double], 
                              responseTemplate: Option[String] = None): String = {
    if (!isRunning.get()) {
      throw new IllegalStateException("Server is shutting down")
    }
    activeRequests.incrementAndGet()
    try {
      val prediction = runInference(modelId, input)
      val modelOutput = Map(
        "prediction" -> prediction._1,
        "confidence" -> prediction._2,
        "model" -> modelId,
        "timestamp" -> System.currentTimeMillis()
      )
      ResponseFormatter.formatResponse(modelOutput, responseTemplate)
    } finally {
      activeRequests.decrementAndGet()
    }
  }

  private def runInference(modelId: String, input: Array[Double]): (String, Double) = {
    // Simulated model inference
    val prediction = if (input.sum > 0) "positive" else "negative"
    val confidence = Math.abs(input.sum) / input.length
    (prediction, Math.min(confidence, 1.0))
  }

  def gracefulShutdown(): Unit = {
    println("Initiating graceful shutdown...")
    isRunning.set(false)
    // Wait for active requests to complete
    val deadline = System.currentTimeMillis() + 30000
    while (activeRequests.get() > 0 && System.currentTimeMillis() < deadline) {
      Thread.sleep(100)
    }
    if (activeRequests.get() > 0) {
      println(s"Warning: ${activeRequests.get()} requests still active at shutdown")
    }
    shutdownLatch.countDown()
    println("Server shutdown complete")
  }

  def awaitTermination(): Unit = {
    shutdownLatch.await()
  }
}

object Main extends App {
  val server = new InferenceServer(8080)
  server.start()

  // Example usage
  val result = server.handleInferenceRequest(
    "sentiment-v2",
    Array(0.5, 0.3, -0.1, 0.8),
    Some("Model: ${model} | Result: ${prediction} (#{format:confidence|percent})")
  )
  println(result)

  server.gracefulShutdown()
}
